public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int hash = 1;
    for (long element : array) {
        int part1 = (int) (element & 0xFFFFFFFFL);
        int part2 = (int) ((element >> 32) & 0xFFFFFFFFL);
        hash = 31 * hash + part1;
        hash = 31 * hash + part2;
    }
    return hash;
}
