public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Create two sets of vertices for the bipartite graph
    Set<String> set1 = new HashSet<>();
    Set<String> set2 = new HashSet<>();

    // Populate the sets with vertices based on the resultMap
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("A")) {
            set1.add(entry.getKey());
        } else if (entry.getKey().startsWith("B")) {
            set2.add(entry.getKey());
        } else {
            throw new IllegalArgumentException("Vertex keys must start with 'A' or 'B'");
        }
    }

    // Add vertices to the graph
    for (String vertex : set1) {
        target.addVertex(vertex);
    }
    for (String vertex : set2) {
        target.addVertex(vertex);
    }

    // Add edges between the two sets of vertices
    for (String v1 : set1) {
        for (String v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
}
