public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType parameterizedType) {
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type actualTypeArgument = actualTypeArguments[i];
            if (actualTypeArgument instanceof Class<?> clazz) {
                result[i] = clazz;
            } else if (actualTypeArgument instanceof ParameterizedType nestedParameterizedType) {
                result[i] = (Class<?>) nestedParameterizedType.getRawType();
            } else {
                return null;
            }
        }
        return result;
    }
    return null;
}
