public long readLong(final int offset) {
    if (offset < 0 || offset > this.length - 8) {
        throw new IllegalArgumentException("Invalid offset for reading a long value");
    }
    int int1 = this.data[offset] & 0xFF;
    int int2 = this.data[offset + 1] & 0xFF;
    int int3 = this.data[offset + 2] & 0xFF;
    int int4 = this.data[offset + 3] & 0xFF;
    int int5 = this.data[offset + 4] & 0xFF;
    int int6 = this.data[offset + 5] & 0xFF;
    int int7 = this.data[offset + 6] & 0xFF;
    int int8 = this.data[offset + 7] & 0xFF;
    return ((long) int1 << 56) |
           ((long) int2 << 48) |
           ((long) int3 << 40) |
           ((long) int4 << 32) |
           ((long) int5 << 24) |
           ((long) int6 << 16) |
           ((long) int7 << 8) |
           (int8 & 0xFF);
}
