static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from the time bucket
        int year = (int) (timeBucket / 100000000);
        int month = (int) ((timeBucket / 1000000) % 100);
        int day = (int) ((timeBucket / 10000) % 100);

        // Adjust the day based on the dayStep
        if (dayStep > 0 && day < 28) {
            day = day - (day % dayStep);
            if (day < 1) {
                day = 1; // Ensure day is at least 1
            }
        } else if (dayStep > 0 && day >= 28) {
            day = day + (7 - (day % 7)) % dayStep;
        }

        // Reconstruct the time bucket
        long compressedTimeBucket = (long) year * 100000000 + (long) month * 1000000 + (long) day * 10000;

        return compressedTimeBucket;
    } catch (ArithmeticException e) {
        // Handle potential arithmetic issues, e.g., division by zero
        return -1;
    } catch (Exception e) {
        // Handle any unexpected exceptions
        return -1;
    }
}
