public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }

    int utf8Size = 0;
    int endIndex = index + len;

    for (int i = index; i < endIndex; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            utf8Size++; // 1-byte character
        } else if (c <= 0x7FF) {
            utf8Size += 2; // 2-byte character
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < endIndex && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                utf8Size += 4; // 4-byte character
                i++; // Skip the next character as it's part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
        } else {
            utf8Size += 3; // 3-byte character
        }
    }

    return utf8Size;
}
