public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1) {
        throw new IllegalArgumentException("desiredCapacity must be at least 1");
    }

    int target = (desiredCapacity >= 1000) ? (int) (desiredCapacity * 1.1) : desiredCapacity;

    while (!isPrime(target)) {
        target++;
    }

    return target;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number == 2) {
        return true;
    }
    if (number % 2 == 0) {
        return false;
    }
    for (int i = 3; i <= Math.sqrt(number); i += 2) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}
