public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    boolean inLiteral = false;
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\' && i + 1 < str.length()) {
            inLiteral = true;
            i++;
            ch = str.charAt(i);
            if (ch == 'b') {
                sb.append('\b');
            } else if (ch == 't') {
                sb.append('\t');
            } else if (ch == 'n') {
                sb.append('\n');
            } else if (ch == 'f') {
                sb.append('\f');
            } else if (ch == 'r') {
                sb.append('\r');
            } else if (ch == '\\') {
                sb.append('\\');
            } else if (ch == '\'') {
                sb.append('\'');
            } else if (ch == '"') {
                sb.append('"');
            } else {
                throw new IllegalArgumentException("Invalid escape sequence: \\" + ch);
            }
        } else if (inLiteral) {
            sb.append('\\');
            sb.append(ch);
            inLiteral = false;
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}
