final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    if (classFileBuffer[constantPoolEntryIndex] != (byte) 1) {
        throw new IllegalArgumentException("Entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8 entry");
    }
    int offset = constantPoolEntryIndex + 1;
    int stringLength = classFileBuffer[offset++] & 0xFF;
    if (offset + stringLength * 2 > charBuffer.length) {
        throw new IllegalArgumentException("Provided charBuffer is too small to hold the UTF-8 string");
    }
    for (int i = 0; i < stringLength; i++) {
        charBuffer[offset / 2] = (char) ((classFileBuffer[offset++] & 0xFF) << 8 | (classFileBuffer[offset++] & 0xFF));
    }
    return new String(charBuffer, 0, stringLength);
}
