private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    if (prev == null) {
        if (next == null) {
            throw new IllegalStateException("Node is already unlinked");
        }
        next.prev = null;
    } else {
        prev.next = next;
    }
    if (next == null) {
        // Node is the last element
        throw new IllegalStateException("Node is already unlinked");
    } else {
        next.prev = prev;
    }
    node.prev = null;
    node.next = null;
    node.element = null;
    return true;
}
