/** 
 * Computes the global separator list of the  {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
 * @return the list of minimal separators of every edge $e$ in the inspected graph
 */
private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList(Graph<Integer, E> graph) {
    List<Pair<List<Pair<Integer,Integer>>, E>> result = new ArrayList<>();

    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    for (Map.Entry<E, Set<Integer>> entry : graph.edges().entrySet()) {
        E edge = entry.getKey();
        Set<Integer> edgeVertices = entry.getValue();

        if (edgeVertices == null || edgeVertices.size() != 2) {
            throw new IllegalArgumentException("Invalid edge vertices for edge: " + edge);
        }

        int v1 = edgeVertices.iterator().next();
        int v2 = edgeVertices.iterator().next();

        List<Pair<Integer,Integer>> separators = findMinimalSeparators(graph, v1, v2);
        result.add(new Pair<>(separators, edge));
    }

    return result;
}

private List<Pair<Integer,Integer>> findMinimalSeparators(Graph<Integer, ?> graph, int v1, int v2) {
    List<Pair<Integer,Integer>> separators = new ArrayList<>();

    Set<Integer> v1Neighbors = graph.adjacentVertices(v1);
    Set<Integer> v2Neighbors = graph.adjacentVertices(v2);

    for (Integer neighbor : v1Neighbors) {
        if (neighbor == v2) {
            continue;
        }

        Set<Integer> commonNeighbors = new HashSet<>(v1Neighbors);
        commonNeighbors.retainAll(v2Neighbors);
        commonNeighbors.remove(neighbor);

        if (!commonNeighbors.isEmpty()) {
            separators.add(new Pair<>(v1, neighbor));
        }
    }

    return separators;
}
