private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph and vertices must be non-null and vertices must not be empty.");
    }

    for (V v1 : vertices) {
        if (!graph.containsVertex(v1)) {
            throw new IllegalArgumentException("Graph does not contain one or more of the vertices.");
        }
    }

    Set<V> remainingVertices = new HashSet<>(vertices);
    while (!remainingVertices.isEmpty()) {
        V vertex = remainingVertices.iterator().next();
        remainingVertices.remove(vertex);
        for (V otherVertex : remainingVertices) {
            if (!graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }

    return true;
}
