public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    try {
        java.nio.file.Path basePath = java.nio.file.Paths.get(path);
        java.nio.file.Path relativePathObj = java.nio.file.Paths.get(relativePath);
        java.nio.file.Path fullPath = basePath.resolve(relativePathObj);
