import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || timeRanges == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Assuming the format of ThreadSnapshot is "timestamp,threadId,threadName"
            String[] parts = line.split(",");
            if (parts.length == 3) {
                long timestamp = Long.parseLong(parts[0]);
                long threadId = Long.parseLong(parts[1]);
                String threadName = parts[2];
                ProfileAnalyzeTimeRange timeRange = findMatchingTimeRange(timeRanges, timestamp);
                if (timeRange != null) {
                    ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadId, threadName);
                    snapshots.add(snapshot);
                }
            }
        }
    }
    return snapshots;
}

private static ProfileAnalyzeTimeRange findMatchingTimeRange(List<ProfileAnalyzeTimeRange> timeRanges, long timestamp) {
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (timestamp >= range.getStartTimestamp() && timestamp <= range.getEndTimestamp()) {
            return range;
        }
    }
    return null;
}
